@media screen and (max-width: 1024px) {
  .ty_krds .sch_tbl_wrap .sch_nomal_tbl .tbl_group { width: 100%; display: flex; flex-wrap: wrap; }
  .ty_krds .sch_tbl_wrap .sch_add_tbl .tbl_group { width: 100%; display: block; }
  .ty_krds .sch_tbl_wrap .sch_add_tbl .tbl_group.line { display: flex !important; align-items: center; }
  .ty_krds .sch_tbl_wrap .sch_add_tbl .tbl_group.line .tbl_block_txt { flex-shrink: 0; }
  .ty_krds .sch_tbl_wrap .sch_add_tbl .tbl_group.line .tbl_input { flex: 1 1 0%; }
  .ty_krds .sch_tbl_wrap .sch_nomal_tbl .tbl_th, .ty_krds .sch_tbl_wrap .sch_add_tbl .tbl_group .tbl_th { width: 100%; display: block; height: auto; padding: 5px 0px; clear: both; }
  .ty_krds .sch_tbl_wrap .tbl_group span.tbl_btn_input { padding: 0px; width: 100%; }
  .ty_krds .sch_tbl_wrap .tbl_group .tbl_td { width: calc(100% - 105px); padding: 0px 0px 5px; }
  .ty_krds .sch_tbl_wrap .tbl_group .tbl_td.full { width: 100%; }
  .ty_krds .sch_tbl_wrap .tbl_group .tbl_td.m_col20 { width: 100px; margin-left: 5px; }
  .ty_krds .sch_tbl_wrap .tbl_block_group .tbl_txt_input_btn input { width: 100%; }
  .ty_krds .sch_tbl_wrap .tbl_group_btn { padding-bottom: 0px; }
  .sch_tbl_wrap .tbl_txt, .sch_tbl_wrap .tbl_txt_input input { float: none; }
  .ty_krds .sch_block_wrap { display: flex; }
  .ty_krds .sch_block_wrap li { margin-right: 0px; }
  .ty_krds .sch_tbl_wrap .tbl_group_btn .tbl_input_btn_m button { position: static; width: 120px; margin-top: 0px; display: block !important; }
  .ty_krds.sch_pop_wrap .layer_popup .popup_contents .btn_wrap { flex-flow: column; }
  .ty_krds.sch_pop_wrap .layer_popup .popup_contents .btn_wrap .btn { min-height: 40px; line-height: 1.1; display: flex !important; }
}
@media screen and (max-width: 768px) {
  .ty_krds .tbl_group_grid { grid-template-columns: repeat(1, 1fr); }
  .ty_krds .sch_tbl_wrap .sch_add_tbl .tbl_group .tbl_group { display: block; }
  .ty_krds .sch_tbl_wrap .tbl_group > span { display: block; }
  .ty_krds .sch_tbl_wrap .tbl_group > span.em { padding: 0px; }
  .ty_krds .sch_tbl_wrap .m_col50 { width: 100%; }
  .ty_krds .sch_tbl_wrap .sch_add_tbl .tbl_group > span.tbl_td { width: 100%; padding-top: 5px; }
}
.close_edit_btn_modal > .btn_close { position: absolute; top: 0px; right: 0px; display: block; padding: 24px 24px 20px 20px; z-index: 12; }
.close_edit_btn_modal > .btn_close .sp { width: 18px; height: 18px; background-position: -211px 0px; }
.close_edit_btn_modal .sp2 { background: url("https://www.nl.go.kr/resource/templete/nl/common/img/common/btn_close.png") center center no-repeat !important; }
@media (max-width: 767px) {
  .close_edit_btn_modal > .btn_close { padding: 14px; }
  .close_edit_btn_modal > .btn_close .sp { display: inline-block; overflow: hidden; background: url("https://www.nl.go.kr/resource/templete/nl/common/img/common/sp.png") -211px 0px no-repeat; font-size: 5px; color: transparent; vertical-align: top; }
}
.search_tip.sch_tips2 { position: absolute; min-width: 450px; max-width: 450px; color: rgb(0, 0, 0); background: rgb(255, 255, 255); min-height: 30px; padding: 5px 10px 10px; display: none; font-size: 14px; border: 1px solid rgb(166, 166, 166); font-weight: 400; text-align: left; box-sizing: border-box; border-radius: 15px 0px 15px 15px; }
.search_tip.sch_tips2::before { content: ""; position: absolute; top: 16px; right: 0px; margin-right: -9px; margin-top: -17px; width: 0px; height: 0px; border-left: 8px solid rgb(166, 166, 166); border-bottom: 8px solid transparent; border-top: 8px solid transparent; }
.search_tip.sch_tips2::after { content: ""; position: absolute; top: 16px; right: 0px; margin-right: -8px; margin-top: -16px; width: 0px; height: 0px; border-left: 8px solid rgb(255, 255, 255); border-bottom: 7px solid transparent; border-top: 7px solid transparent; }
.search_tip.sch_tips2.active { display: block; left: 180px; z-index: 999; }
.search_tip.sch_tips2 b { font-size: 14px; display: block; margin: 5px 0px; font-weight: 400; color: rgb(0, 0, 0); }
.search_tip.sch_tips2 b:first-of-type { font-size: 16px; font-weight: 600; }
.search_tip.sch_tips2 a.close { top: 10px; right: 10px; line-height: 13px; position: absolute !important; }
.search_tip.sch_tips2 a:not(.close) { font-size: 14px; border-bottom: 1px solid; }
.search_tip.sch_tips2 a:not(.close)::after { content: "" !important; display: inline-block !important; position: relative !important; margin-left: 4px !important; width: 17px !important; height: 17px !important; background: url("/resource/templete/nl/common/img/common/new_24jan/icon_blank.png") center center / 17px auto no-repeat !important; vertical-align: middle !important; }
.search_tip.sch_tips2 span { display: block; }
@media (max-width: 946px) {
  .search_tip.sch_tips2.active { left: 0px; width: 100%; min-width: auto; }
}
